\section*{Claim}
For the two-dimensional Kitaev quantum double with an orientable subsystem
$X=\Sigma_{\gamma_X,n}$, let the boundary anyon label be
\[
\alpha_\varphi=(\alpha_1,\ldots,\alpha_n),
\qquad
\alpha_j\in\operatorname{Rep}(C_{c_j}),
\qquad
\varphi=(c_1,\ldots,c_n).
\]
Define
\[
S_{(g,\beta),(c,\alpha)}:=\frac{1}{|C_g||C_c|}
\sum_{h\in G:\ h^{-1}gh\in C_c}\chi_\beta(hch^{-1})\chi_\alpha(h^{-1}gh).
\]
If
\[
x^X_{\alpha_\varphi}:=\sum_{[g]}\sum_{\beta\in\operatorname{Rep}(C_g)}
S_{(g,\beta),(1,1)}^{2-2\gamma_X-n}
\prod_{j=1}^{n}S_{(g,\beta),(c_j,\alpha_j)},
\]
and $y^Y_{\alpha_\varphi}$ is defined by the same formula for an orientable
$Y=\Sigma_{\gamma_Y,n}$, then the gauge-invariant entanglement block labelled by
$([\varphi],\alpha_\varphi)$ has small matrix
\[
\Psi_{\varphi,\alpha_\varphi}\in
\mathbb{C}^{x^X_{\alpha_\varphi}\times y^Y_{\alpha_\varphi}}.
\]
Therefore its number of independent entanglement singular values is at most
\[
\min\{x^X_{\alpha_\varphi},y^Y_{\alpha_\varphi}\},
\]
with equality for a full-rank small matrix, and every positive reduced-density-matrix level in this sector has degeneracy
\[
|G|^{|V_\partial|-n}|[\varphi]|\prod_{j=1}^{n}d_{\alpha_j}.
\]
Thus the orientable full entanglement-spectrum multiplicities are exactly the finite-group quantum-double sector-counting sums built from the $S$ matrix.

\section*{Premises}
\begin{align*}
(P1)\;&\text{In the two-dimensional orientable quantum-double specialization, the multiplicity of }
\alpha_\varphi\text{ on }X\text{ is }x^X_{\alpha_\varphi}\text{ as defined above}.\\
(P2)\;&\text{The corresponding multiplicity on orientable }Y\text{ is }y^Y_{\alpha_\varphi}\text{ with }\gamma_X\text{ replaced by }\gamma_Y.\\
(P3)\;&\text{The gauge-invariant topological block for }([\varphi],\alpha_\varphi)
\text{ is }\mathbb{C}^{x^X_{\alpha_\varphi}\times y^Y_{\alpha_\varphi}}\otimes\mathbf{1}_{d_{\alpha_\varphi}}.\\
(P4)\;&d_{\alpha_\varphi}=\prod_{j=1}^{n}d_{\alpha_j}.\\
(P5)\;&\text{The orbit and geometric degeneracies multiply each positive level by }|[\varphi]|\text{ and }|G|^{|V_\partial|-n}.\\
(P6)\;&\text{A matrix in }\mathbb{C}^{x\times y}\text{ has at most }\min\{x,y\}\text{ nonzero singular values, and this bound is attained by a full-rank matrix.}
\end{align*}

\section*{Derivation}
By (P1), the row multiplicity in the block labelled by $\alpha_\varphi$ is exactly
\begin{align*}
x^X_{\alpha_\varphi}
&=\sum_{[g]}\sum_{\beta\in\operatorname{Rep}(C_g)}
S_{(g,\beta),(1,1)}^{2-2\gamma_X-n}
\prod_{j=1}^{n}S_{(g,\beta),(c_j,\alpha_j)}.
\end{align*}
By (P2), the column multiplicity is the analogous number $y^Y_{\alpha_\varphi}$. Hence (P3) gives
\begin{align*}
\Psi_{\varphi,\alpha_\varphi}&\in
\mathbb{C}^{x^X_{\alpha_\varphi}\times y^Y_{\alpha_\varphi}}.
\end{align*}
The number of independent positive singular values carried by this small matrix is therefore
\begin{align*}
\operatorname{rank}\Psi_{\varphi,\alpha_\varphi}
&\le\min\{x^X_{\alpha_\varphi},y^Y_{\alpha_\varphi}\} &&\text{by (P6),}
\end{align*}
and equality is possible when the small matrix has full rank. Finally, each positive singular-value level is copied by the geometric degeneracy, the orbit degeneracy, and the irrep dimension. By (P4),(P5), this total degeneracy is
\begin{align*}
|G|^{|V_\partial|-n}|[\varphi]|d_{\alpha_\varphi}
&=|G|^{|V_\partial|-n}|[\varphi]|\prod_{j=1}^{n}d_{\alpha_j}.
\end{align*}
Thus the same $S$-matrix sums that count quantum-double boundary Hilbert-space multiplicities are precisely the integers controlling the entanglement-spectrum block sizes.

\section*{Final Result}
\[
\boxed{\Psi_{\varphi,\alpha_\varphi}\in
\mathbb{C}^{x^X_{\alpha_\varphi}\times y^Y_{\alpha_\varphi}},
\qquad
\#\operatorname{levels}_{[\varphi],\alpha_\varphi}\le
\min\{x^X_{\alpha_\varphi},y^Y_{\alpha_\varphi}\},
\qquad
\operatorname{degeneracy}=|G|^{|V_\partial|-n}|[\varphi]|\prod_{j=1}^{n}d_{\alpha_j}}
\]
\hfill$\blacksquare$

