\section*{Claim}
For the two-dimensional Kitaev quantum double with a non-orientable subsystem
$X=N_{k_X,n}$, $k_X\ge 1$, let
\[
\varphi=(c_1,\ldots,c_n),
\qquad
\alpha_\varphi=(\alpha_1,\ldots,\alpha_n),
\qquad
\alpha_j\in\operatorname{Rep}(C_{c_j}).
\]
For $\beta\in\operatorname{Rep}(C_g)$ define the Frobenius-Schur indicator
\[
\iota_\beta:=\frac{1}{|C_g|}\sum_{t\in C_g}\chi_\beta(t^2).
\]
If
\[
x^X_{\alpha_\varphi}:=\sum_{[g]}\sum_{\beta\in\operatorname{Rep}(C_g)}
\iota_\beta^{k_X}S_{(g,\beta),(1,1)}^{2-k_X-n}
\prod_{j=1}^{n}S_{(g,\beta),(c_j,\alpha_j)},
\]
and $y^Y_{\alpha_\varphi}$ is defined by the same non-orientable formula for
$Y=N_{k_Y,n}$, then the block labelled by $([\varphi],\alpha_\varphi)$ has small matrix
\[
\Psi_{\varphi,\alpha_\varphi}\in
\mathbb{C}^{x^X_{\alpha_\varphi}\times y^Y_{\alpha_\varphi}}.
\]
Consequently,
\[
\#\operatorname{levels}_{[\varphi],\alpha_\varphi}\le
\min\{x^X_{\alpha_\varphi},y^Y_{\alpha_\varphi}\},
\qquad
\operatorname{degeneracy}=|G|^{|V_\partial|-n}|[\varphi]|\prod_{j=1}^{n}d_{\alpha_j}.
\]
Thus the non-orientable entanglement-spectrum multiplicities are exactly the finite-group quantum-double sector counts with crosscaps inserted through Frobenius-Schur indicators.

\section*{Premises}
\begin{align*}
(P1)\;&G\text{ is finite, }C_g:=\{a\in G:ag=ga\},\text{ and }[g]\text{ ranges over conjugacy classes}.\\
(P2)\;&S_{(g,\beta),(c,\alpha)}:=\frac{1}{|C_g||C_c|}
\sum_{h\in G:\ h^{-1}gh\in C_c}\chi_\beta(hch^{-1})\chi_\alpha(h^{-1}gh).\\
(P3)\;&\iota_\beta:=|C_g|^{-1}\sum_{t\in C_g}\chi_\beta(t^2).\\
(P4)\;&\text{For }X=N_{k_X,n},\text{ the quantum-double boundary multiplicity is the stated }
\iota_\beta^{k_X}S\text{-matrix sum }x^X_{\alpha_\varphi}.\\
(P5)\;&\text{For }Y=N_{k_Y,n},\text{ the column multiplicity }y^Y_{\alpha_\varphi}\text{ is obtained by replacing }k_X\text{ with }k_Y.\\
(P6)\;&\text{The gauge-invariant block for }([\varphi],\alpha_\varphi)\text{ is }
\mathbb{C}^{x^X_{\alpha_\varphi}\times y^Y_{\alpha_\varphi}}\otimes\mathbf{1}_{d_{\alpha_\varphi}}.\\
(P7)\;&d_{\alpha_\varphi}=\prod_{j=1}^{n}d_{\alpha_j}.\\
(P8)\;&\text{Every positive level is copied by geometric degeneracy }|G|^{|V_\partial|-n}
\text{ and orbit degeneracy }|[\varphi]|.\\
(P9)\;&\operatorname{rank}\Psi\le\min\{x,y\}\text{ for }\Psi\in\mathbb{C}^{x\times y}.
\end{align*}

\section*{Derivation}
By (P4), a non-orientable subsystem contributes
\begin{align*}
x^X_{\alpha_\varphi}
&=\sum_{[g]}\sum_{\beta\in\operatorname{Rep}(C_g)}
\iota_\beta^{k_X}S_{(g,\beta),(1,1)}^{2-k_X-n}
\prod_{j=1}^{n}S_{(g,\beta),(c_j,\alpha_j)}.
\end{align*}
The factor $\iota_\beta^{k_X}$ is exactly the crosscap contribution, because each crosscap inserts one Frobenius-Schur indicator by (P3),(P4). By (P5), the other side contributes $y^Y_{\alpha_\varphi}$ with $k_X$ replaced by $k_Y$. Substituting these multiplicities into the general gauge-invariant block formula (P6) gives
\begin{align*}
\Psi_{\varphi,\alpha_\varphi}&\in
\mathbb{C}^{x^X_{\alpha_\varphi}\times y^Y_{\alpha_\varphi}}.
\end{align*}
Therefore the number of independent positive singular values in this sector is
\begin{align*}
\operatorname{rank}\Psi_{\varphi,\alpha_\varphi}
&\le\min\{x^X_{\alpha_\varphi},y^Y_{\alpha_\varphi}\} &&\text{by (P9).}
\end{align*}
By (P7),(P8), each positive level has degeneracy
\begin{align*}
|G|^{|V_\partial|-n}|[\varphi]|d_{\alpha_\varphi}
&=|G|^{|V_\partial|-n}|[\varphi]|\prod_{j=1}^{n}d_{\alpha_j}.
\end{align*}
Thus non-orientable Li-Haldane counting is not an additional assumption: it is obtained by replacing the orientable multiplicity with the Frobenius-Schur-weighted quantum-double multiplicity and then applying the same orbit, irrep, and geometric degeneracy accounting.

\section*{Final Result}
\[
\boxed{x^X_{\alpha_\varphi}=\sum_{[g]}\sum_{\beta\in\operatorname{Rep}(C_g)}
\iota_\beta^{k_X}S_{(g,\beta),(1,1)}^{2-k_X-n}
\prod_{j=1}^{n}S_{(g,\beta),(c_j,\alpha_j)},
\quad
\Psi_{\varphi,\alpha_\varphi}\in\mathbb{C}^{x^X_{\alpha_\varphi}\times y^Y_{\alpha_\varphi}},
\quad
\operatorname{degeneracy}=|G|^{|V_\partial|-n}|[\varphi]|\prod_{j=1}^{n}d_{\alpha_j}}
\]
\hfill$\blacksquare$
